\documentclass{article}
\usepackage[utf8]{inputenc}
\usepackage{amsmath}
\usepackage{calc}
\usepackage{enumitem}
\usepackage{soul}

\begin{document}
\begin{enumerate}[noitemsep,label=\arabic*.]
	\item To solve this problem, we can look for a pair ($x$,$y$) that gives the desired product $xy - (x-4)(2y-1)$ to match the criteria that the product of friend's number is one more than our product. In other words,
	\begin{align*}
		xy &= (x-4)(2y-1) + 1 \\
	\end{align*}

	\item Factoring the right side of the equation gives $(x-4)(2y-1)=(x-4)(2y-1)+x-4-2y+1 -(x-4-2y+1) = xy - 4x + 4y - 3$, so we have
	\begin{align*}
	4x - 4y -3 &= x
	\end{align*}

	\item Solving this equation for $x$ and checking the validity of $x,y$, we get
	\begin{align*}
	 4x -4y -3 + 4y &= x + 4y \\
	 3x &= 5y \\
	 x &= \frac{5}{3}y
	\end{align*}
	Since both $x, y$ are integers between $1$ and $10$, it forces $y=\frac{3}{5}x$. In this case, we have $\frac{3}{5} \times 8 = 4.8$. Since $y$ cannot be greater than ten, we look for valid $x,y$ pairs among the following multiples of $\frac{3}{5}$:
	\begin{itemize}
	 \item $\frac{3}{5}$
	 \item $\frac{6}{5}$
	 \item $\frac{9}{5}$
	 \item $\frac{12}{5}$
	 \item $\frac{15}{5}=3$
	\end{itemize}

	\item We find one valid pair ($x$,$y$) = (3,3). The product of my numbers ($x$,$y$) equals $3\times3=9$.
	\boxed{\colorbox{green!20}{\strut $9$}}
\end{enumerate}

\end{document}

