\documentclass{article}
\usepackage{amsmath,amssymb}
\usepackage{mathtools}

\begin{document}

\begin{enumerate}
    \item Find the length $ED$ of the altitude from $B$ to $\overline{AC}$.
    \begin{align*}
        ED &= \frac{BC \cdot HE}{BC + HE} \\
        HE &= BC - AB = 5 - 5 = 0 \\
        ED &= 0
    \end{align*}

    \item Find the length $DF$ of the altitude from $A$ to $\overline{BC}$.
    \begin{align*}
        DF &= \frac{AB \cdot HD}{AB + HD} \\
        HD &= BC - AC = 5 - 6 = -1 \\
        DF &= 0
    \end{align*}

    \item Calculate the height $HG$ of the triangle formed by crossing the diagonals of $\triangle ABC$.
    \begin{align*}
        HG &= \frac{AF \cdot AG}{AB} \\
        AG &= \sqrt{AC^2 - ED^2} = \sqrt{6^2 - 0^2} = 6 \\
        AF &= BC - AD = 5 - 0 = 5 \\
        HG &= \frac{5 \cdot 6}{5} = 6
    \end{align*}

    \item Calculate the area of $\triangle AHG$.
    \[ \triangle AHG = \frac{1}{2} \cdot AH \cdot HG = \frac{1}{2} \cdot AC \cdot HG = \boxed{ 30 } \]

    \item Since $\triangle DRC$ and $\triangle AHG$ share the base $RC = BC = 5$. To find the corresponding base for $\triangle DRC$, use the height $DF$.
    \[ \triangle DRC = \boxed{ 0 } \]
\end{enumerate}

\end{document}
```

