V &= \pi\left(\left(\frac{-6-\sqrt{-156}}{2}\right)\cdot\overline{\left(\frac{-6-\sqrt{-156}}{2}\right)}\right)(6) \\
&= \pi\left(\frac{(-6-\sqrt{-156})(-6+\sqrt{-156})}{4}\right)(6) \\
&= \pi\left(\frac{-36+6\sqrt{-156}-156+\sqrt{-156}\cdot-6\sqrt{-156}}{4}\right)(6) \\
&= \boxed{\frac{144\pi\sqrt{-156}}{4} && \text{or} && \boxed{\frac{-144\pi\sqrt{-156}}{4}} } \text{ cubic centimeters}
\end{align*}

